        // GET: api/CompanyProgram/company/{companyId}/details
        // Company Portal program cards, sourced from the real database.
        [HttpGet("company/{companyId}/details")]
        [Authorize(Roles = "CompanySupervisor")]
        public async Task<ActionResult<IEnumerable<CompanyProgramSummaryDTO>>> GetDetailsByCompanyId(int companyId)
        {
            if (!await OwnsCompanyAsync(companyId))
                return Forbid();

            var companyExists = await _context.NFD_Companies
                .AsNoTracking()
                .AnyAsync(c => c.CompanyId == companyId);

            if (!companyExists)
                return NotFound(new { message = "Company not found." });

            var approvedProgramIds = await _context.NFD_CompanyPrograms
                .AsNoTracking()
                .Where(cp => cp.CompanyId == companyId)
                .Select(cp => cp.ProgramId)
                .ToListAsync();

            var programIds = approvedProgramIds.Distinct().ToList();

            if (programIds.Count == 0)
                return Ok(Array.Empty<CompanyProgramSummaryDTO>());

            var programs = await _context.NFD_Programs
                .AsNoTracking()
                .Where(p => programIds.Contains(p.ProgramId)
                    && p.Status == Nafadh_Backend.Enums.NFD_ProgramStatus.Published)
                .OrderBy(p => p.Title)
                .Select(p => new CompanyProgramSummaryDTO
                {
                    ProgramId = p.ProgramId,
                    Title = p.Title,
                    Description = p.Description,
                    Category = p.Category,
                    DurationHours = p.DurationHours,
                    Price = p.Price,
                    Status = p.Status.ToString(),
                    ApprovedForCompany = approvedProgramIds.Contains(p.ProgramId),
                    // A company's program approval does not confer ownership of every batch.
                    BatchCount = p.Batches.Count(b => b.CompanyId == companyId ||
                        b.Enrollments.Any(e => e.CompanyId == companyId)),
                    EnrollmentCount = p.Batches
                        .SelectMany(b => b.Enrollments)
                        .Count(e => e.CompanyId == companyId),
                    CurrentTraineeCount = p.Batches
                        .SelectMany(b => b.Enrollments)
                        .Count(e => e.CompanyId == companyId && e.CompletionStatus == Nafadh_Backend.Enums.NFD_EnrollmentCompletionStatus.InProgress),
                    // "Used" = seats currently occupied (InProgress), the same rule the
                    // Company Dashboard uses. Completed / dropped / failed enrollments
                    // no longer occupy a seat (they stay in EnrollmentCount).
                    AllocatedCapacity = p.Batches
                        .Where(b => b.CompanyId == companyId || b.Enrollments.Any(e => e.CompanyId == companyId))
                        .Sum(b => b.Capacity),
                    UsedCapacity = p.Batches.SelectMany(b => b.Enrollments)
                        .Count(e => e.CompanyId == companyId && e.CompletionStatus == Nafadh_Backend.Enums.NFD_EnrollmentCompletionStatus.InProgress),
                    RemainingCapacity = Math.Max(0, (int)p.Batches
                        .Where(b => b.CompanyId == companyId || b.Enrollments.Any(e => e.CompanyId == companyId))
                        .Sum(b => b.Capacity)
                        - p.Batches.SelectMany(b => b.Enrollments)
                            .Count(e => e.CompanyId == companyId && e.CompletionStatus == Nafadh_Backend.Enums.NFD_EnrollmentCompletionStatus.InProgress)),
                    UtilizationPercentage = p.Batches
                        .Where(b => b.CompanyId == companyId || b.Enrollments.Any(e => e.CompanyId == companyId))
                        .Sum(b => b.Capacity) > 0
                        ? Math.Round((decimal)p.Batches.SelectMany(b => b.Enrollments)
                            .Count(e => e.CompanyId == companyId && e.CompletionStatus == Nafadh_Backend.Enums.NFD_EnrollmentCompletionStatus.InProgress) * 100m
                            / p.Batches.Where(b => b.CompanyId == companyId ||
                                b.Enrollments.Any(e => e.CompanyId == companyId)).Sum(b => b.Capacity), 1)
                        : 0m,
                    Departments = p.Batches
                        .SelectMany(b => b.Enrollments)
                        .Where(e => e.CompanyId == companyId && e.Department != null)
                        .Select(e => e.Department!.Name)
                        .Distinct()
                        .OrderBy(x => x)
                        .ToList()
                })
                .ToListAsync();

            var openSeats = await LoadOpenSeatsAsync(companyId, programs.Select(p => p.ProgramId).ToList());
            foreach (var program in programs)
                ApplyOpenSeats(program, openSeats);

            return Ok(programs);
        }

        // GET: api/CompanyProgram/company/{companyId}/program/{programId}/details
        // Full company-scoped details for the Company Portal program-details page.
        [HttpGet("company/{companyId}/program/{programId}/details")]
        [Authorize(Roles = "CompanySupervisor")]
        public async Task<ActionResult<CompanyProgramDetailsDTO>> GetDetails(int companyId, int programId)
        {
            if (!await OwnsCompanyAsync(companyId))
                return Forbid();

            var companyProgram = await _context.NFD_CompanyPrograms
                .AsNoTracking()
                .FirstOrDefaultAsync(cp => cp.CompanyId == companyId && cp.ProgramId == programId);

            if (companyProgram is null)
                return NotFound(new { message = "This program is not approved for the company." });

            var program = await _context.NFD_Programs
                .AsNoTracking()
                .Where(p => p.ProgramId == programId
                    && p.Status == Nafadh_Backend.Enums.NFD_ProgramStatus.Published)
                .Select(p => new
                {
                    p.ProgramId,
                    p.Title,
                    p.Description,
                    p.Category,
                    p.DurationHours,
                    p.Price,
                    Status = p.Status.ToString()
                })
                .FirstOrDefaultAsync();

            if (program is null)
                return NotFound(new { message = "Program not found." });

            var batches = await _context.NFD_Batches
                .AsNoTracking()
                .Where(b => b.ProgramId == programId &&
                    (b.CompanyId == companyId || b.Enrollments.Any(e => e.CompanyId == companyId)))
                .OrderBy(b => b.StartDate)
                .Select(b => new CompanyProgramBatchDTO
                {
                    BatchId = b.BatchId,
                    BatchName = b.BatchName,
                    StartDate = b.StartDate,
                    EndDate = b.EndDate,
                    Capacity = b.Capacity,
                    CompanyEnrollmentCount = b.Enrollments.Count(e => e.CompanyId == companyId),
                    Status = b.Status.ToString(),
                    AttendanceWeight = b.AttendanceWeight,
                    QuizzesWeight = b.QuizzesWeight,
                    TasksWeight = b.TasksWeight,
                    ProjectsWeight = b.ProjectsWeight,
                    ExcellentMinScore = b.ExcellentMinScore,
                    ExcellentMinAttendance = b.ExcellentMinAttendance,
                    VeryGoodMinScore = b.VeryGoodMinScore,
                    VeryGoodMinAttendance = b.VeryGoodMinAttendance,
                    GoodMinScore = b.GoodMinScore,
                    AtRiskMinAttendance = b.AtRiskMinAttendance
                })
                .ToListAsync();

            // Load only the actual batch assignments and plans owned by the current company.
            // A program may have unrelated batches/plans owned by other companies.
            var visibleBatchIds = batches.Select(x => x.BatchId).ToList();
            if (visibleBatchIds.Count > 0)
            {
                var batchTrainers = await _context.NFD_BatchTrainers
                    .AsNoTracking()
                    .Where(bt => visibleBatchIds.Contains(bt.BatchId) &&
                        (bt.Trainer.CompanyId == companyId ||
                         (bt.Trainer.CompanyId == null && bt.Batch.CompanyId == companyId)))
                    .Select(bt => new
                    {
                        bt.BatchId,
                        bt.TrainerId,
                        TrainerName = bt.Trainer.User.FullName
                    })
                    .ToListAsync();
                foreach (var link in batchTrainers)
                {
                    batches.First(x => x.BatchId == link.BatchId).Trainers.Add(new CompanyProgramTrainerAssignmentDTO
                    {
                        TrainerId = link.TrainerId,
                        TrainerName = link.TrainerName,
                        Scope = "Batch"
                    });
                }

                var plans = await _context.NFD_CoursePlans.AsNoTracking()
                    .Where(p => p.CompanyId == companyId && p.ProgramId == programId &&
                        p.BatchId.HasValue && visibleBatchIds.Contains(p.BatchId.Value))
                    .Include(p => p.Trainers).ThenInclude(pt => pt.Trainer).ThenInclude(t => t.User)
                    .Include(p => p.Stages).ThenInclude(st => st.Trainer).ThenInclude(t => t!.User)
                    .Include(p => p.Stages).ThenInclude(st => st.Trainers).ThenInclude(stt => stt.Trainer).ThenInclude(t => t.User)
                    .Include(p => p.Stages).ThenInclude(st => st.Items).ThenInclude(i => i.Trainer).ThenInclude(t => t!.User)
                    .AsSplitQuery().ToListAsync();
                foreach (var plan in plans)
                {
                    var batchDto = batches.First(x => x.BatchId == plan.BatchId);
                    var planDto = new CompanyProgramPlanDTO
                    {
                        PlanId = plan.PlanId, Title = plan.Title, DurationHours = plan.DurationHours,
                        StartDate = plan.StartDate, EndDate = plan.EndDate,
                        ApprovalStatus = plan.ApprovalStatus.ToString(),
                        ExecutionStatus = plan.ExecutionStatus.ToString()
                    };
                    foreach (var pt in plan.Trainers.Where(pt => pt.Trainer.CompanyId == companyId || pt.Trainer.CompanyId == null))
                        batchDto.Trainers.Add(new CompanyProgramTrainerAssignmentDTO
                        {
                            TrainerId = pt.TrainerId,
                            TrainerName = pt.Trainer.User.FullName,
                            Scope = "Plan", PlanId = plan.PlanId
                        });
                    foreach (var stage in plan.Stages.OrderBy(st => st.OrderIndex))
                    {
                        var stageDto = new CompanyProgramStageDTO
                        {
                            StageId = stage.StageId, Title = stage.Title,
                            StartDate = stage.StartDate, EndDate = stage.EndDate,
                            Status = stage.Status.ToString()
                        };
                        var stageTrainers = stage.Trainers
                            .Where(st => st.Trainer.CompanyId == companyId || st.Trainer.CompanyId == null)
                            .Select(st => new CompanyProgramTrainerAssignmentDTO
                        {
                            TrainerId = st.TrainerId, TrainerName = st.Trainer.User.FullName,
                            Scope = "Stage", PlanId = plan.PlanId,
                            StageId = stage.StageId, StageTitle = stage.Title
                        }).ToList();
                        if (stage.TrainerId.HasValue && stage.Trainer is not null &&
                            (stage.Trainer.CompanyId == companyId || stage.Trainer.CompanyId == null) &&
                            !stageTrainers.Any(t => t.TrainerId == stage.TrainerId.Value))
                            stageTrainers.Add(new CompanyProgramTrainerAssignmentDTO
                            {
                                TrainerId = stage.TrainerId.Value,
                                TrainerName = stage.Trainer.User.FullName,
                                Scope = "Stage", PlanId = plan.PlanId,
                                StageId = stage.StageId, StageTitle = stage.Title
                            });
                        stageDto.Trainers.AddRange(stageTrainers);
                        batchDto.Trainers.AddRange(stageTrainers);
                        foreach (var item in stage.Items.Where(i => i.TrainerId.HasValue && i.Trainer != null &&
                            (i.Trainer.CompanyId == companyId || i.Trainer.CompanyId == null)))
                            batchDto.Trainers.Add(new CompanyProgramTrainerAssignmentDTO
                            {
                                TrainerId = item.TrainerId!.Value,
                                TrainerName = item.Trainer!.User.FullName,
                                Scope = "Item", PlanId = plan.PlanId,
                                StageId = stage.StageId, StageTitle = stage.Title,
                                ItemId = item.ItemId, ItemTitle = item.Title
                            });
                        planDto.Stages.Add(stageDto);
                    }
                    batchDto.Plans.Add(planDto);
                }
            }

            // The stored Batch.Status is edited by hand and drifts away from the dates
            // (e.g. "Ongoing" for a batch that ended last month). The portal shows the
            // status that matches the dates; only an explicit cancellation is kept.
            var today = DateTime.Today;
            foreach (var batch in batches)
                batch.Status = DeriveBatchStatus(batch.Status, batch.StartDate, batch.EndDate, today);

            var enrollments = await _context.NFD_Enrollments
                .AsNoTracking()
                .Include(e => e.Trainee).ThenInclude(t => t.User)
                .Include(e => e.Batch)
                .Include(e => e.Department)
                .Include(e => e.CompanySupervisor).ThenInclude(s => s!.User)
                .Where(e => e.CompanyId == companyId && e.Batch.ProgramId == programId)
                .OrderBy(e => e.Trainee.User.FullName)
                .ToListAsync();

            var modules = await _context.NFD_Modules
                .AsNoTracking()
                .Where(m => m.ProgramId == programId && !m.IsArchived)
                .OrderBy(m => m.OrderIndex)
                .Select(m => new CompanyProgramModuleDTO
                {
                    ModuleId = m.ModuleId,
                    Title = m.Title,
                    OrderIndex = m.OrderIndex,
                    PrerequisiteModuleId = m.PrerequisiteModuleId
                })
                .ToListAsync();

            // Progress per enrollment, computed in two queries instead of one
            // /Enrollment/{id}/progress-summary call per row from the browser.
            // Same rule as EnrollmentService.GetProgressSummaryAsync:
            // completed modules / all modules of the program.
            var allModuleIds = await _context.NFD_Modules
                .AsNoTracking()
                .Where(m => m.ProgramId == programId)
                .Select(m => m.ModuleId)
                .ToListAsync();

            var traineeIds = enrollments.Select(e => e.TraineeId).Distinct().ToList();

            var completedByTrainee = allModuleIds.Count == 0 || traineeIds.Count == 0
                ? new Dictionary<int, int>()
                : await _context.NFD_TraineeModuleProgresses
                    .AsNoTracking()
                    .Where(mp => traineeIds.Contains(mp.TraineeId)
                                 && allModuleIds.Contains(mp.ModuleId)
                                 && mp.Status == Nafadh_Backend.Enums.NFD_ModuleProgressStatus.Completed)
                    .GroupBy(mp => mp.TraineeId)
                    .Select(g => new { TraineeId = g.Key, Count = g.Select(x => x.ModuleId).Distinct().Count() })
                    .ToDictionaryAsync(x => x.TraineeId, x => x.Count);

            var activeCount = enrollments.Count(e =>
                e.CompletionStatus == Nafadh_Backend.Enums.NFD_EnrollmentCompletionStatus.InProgress);

            var departments = enrollments
                .Where(e => e.Department is not null)
                .Select(e => e.Department!.Name)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(x => x)
                .ToList();

            var result = new CompanyProgramDetailsDTO
            {
                ProgramId = program.ProgramId,
                Title = program.Title,
                Description = program.Description,
                Category = program.Category,
                DurationHours = program.DurationHours,
                Price = program.Price,
                Status = program.Status,
                ApprovedForCompany = companyProgram is not null,
                BatchCount = batches.Count,
                EnrollmentCount = enrollments.Count,
                CurrentTraineeCount = activeCount,
                AllocatedCapacity = batches.Sum(b => b.Capacity),
                UsedCapacity = activeCount,
                RemainingCapacity = Math.Max(0, (int)batches.Sum(b => b.Capacity) - activeCount),
                UtilizationPercentage = batches.Sum(b => b.Capacity) > 0
                    ? Math.Round((decimal)activeCount * 100m / batches.Sum(b => b.Capacity), 1)
                    : 0m,
                Departments = departments,
                Batches = batches,
                Enrollments = enrollments.Select(e => new CompanyProgramEnrollmentDTO
                {
                    EnrollmentId = e.EnrollmentId,
                    TraineeId = e.TraineeId,
                    TraineeName = e.Trainee?.User?.FullName ?? string.Empty,
                    DepartmentName = e.Department?.Name,
                    SupervisorName = e.CompanySupervisor?.User?.FullName,
                    BatchName = e.Batch?.BatchName ?? string.Empty,
                    CompletionStatus = e.CompletionStatus.ToString(),
                    TraineeGitHubUrl = e.Trainee?.GitHubUrl,
                    TraineeLinkedInUrl = e.Trainee?.LinkedInUrl,
                    ProgressPercentage = allModuleIds.Count == 0
                        ? 0
                        : Math.Round(
                            (completedByTrainee.TryGetValue(e.TraineeId, out var done) ? done : 0)
                            * 100.0 / allModuleIds.Count, 1)
                }).ToList(),
                Modules = modules
            };

            ApplyOpenSeats(result, await LoadOpenSeatsAsync(companyId, new List<int> { programId }));

            return Ok(result);
        }

        // GET: api/CompanyProgram/company/{companyId}/capacity
        // Company capacity for the Specialties header. Same rule as the Company
        // Dashboard: Used = unique trainees with an InProgress enrollment.
        // (Replaces the unauthenticated api/Company/{id}/capacity call, which
        // counted every enrollment regardless of status.)
        [HttpGet("company/{companyId}/capacity")]
        [Authorize(Roles = "CompanySupervisor")]
        public async Task<ActionResult<CompanyDashboardCapacityDTO>> GetCapacity(int companyId)
        {
            if (!await OwnsCompanyAsync(companyId))
                return Forbid();

            var company = await _context.NFD_Companies
                .AsNoTracking()
                .FirstOrDefaultAsync(c => c.CompanyId == companyId);

            if (company is null)
                return NotFound(new { message = "Company not found." });

            var used = await _context.NFD_Enrollments
                .AsNoTracking()
                .Where(e => e.CompanyId == companyId
                            && e.CompletionStatus == Nafadh_Backend.Enums.NFD_EnrollmentCompletionStatus.InProgress)
                .Select(e => e.TraineeId)
                .Distinct()
                .CountAsync();

            return Ok(new CompanyDashboardCapacityDTO
            {
                Total = company.Capacity,
                Used = used,
                Remaining = Math.Max(0, company.Capacity - used)
            });
        }

